use peritheos::isothermal::BM3;
use peritheos::thermal::QCompromiseDebye;
use peritheos::{load_eosmat, load_eosmat_str, IsothermalEos, ThermalEos};
use std::path::Path;

#[test]
fn source_pressure_and_constant_thermal_increment() {
    let cold = BM3::new(11.313, 169.339, 4.55314).unwrap();
    let model = QCompromiseDebye::new(cold, 298.0, 771.096, 1.1847, 20.0).unwrap();
    // Independent SI/SciPy Debye quadrature, not generated by this Rust evaluator.
    assert!((model.pressure(10.5, 1000.0).unwrap() - 18.309_189_449_6).abs() < 2e-9);
    for v in [9.6, 10.5, 11.313] {
        assert_eq!(model.thermal_pressure(v, 298.0).unwrap(), 0.0);
        assert!(
            (model.thermal_pressure(v, 1000.0).unwrap()
                - model.thermal_pressure(11.313, 1000.0).unwrap())
            .abs()
                < 1e-12
        );
        assert!(
            (model.bulk_modulus(v, 1000.0, 1e-6).unwrap() - cold.bulk_modulus(v).unwrap()).abs()
                < 2e-6
        );
        let pressure = model.pressure(v, 1000.0).unwrap();
        assert!((model.volume(pressure, 1000.0).unwrap() - v).abs() < 1e-8);
        assert!((model.temperature(pressure, v).unwrap() - 1000.0).abs() < 1e-4);
    }
    assert!(model.pressure(0.0, 1000.0).is_err());
    assert!(model.pressure(11.0, 0.0).is_err());
    assert!(QCompromiseDebye::new(cold, 298.0, -1.0, 1.0, 20.0).is_err());
    assert!(QCompromiseDebye::new(cold, 298.0, 700.0, f64::NAN, 20.0).is_err());
}

#[test]
fn native_material_loading_preserves_covariance_and_volume_units() {
    for name in ["pyrope", "grossular"] {
        let path = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join(format!("../../peritheos/data/materials/{name}.eosmat"));
        if !path.exists() {
            continue;
        } // Bundled data are outside crates.io sources.
        let material = load_eosmat(&path).unwrap();
        let identifier = format!("{name}_angel_2022_bm3_q_compromise_debye");
        let record = material.record(&identifier).unwrap();
        let v = if name == "pyrope" { 1500.0 } else { 1650.0 };
        let pressure = record.pressure(v, 1000.0).unwrap();
        let restored = load_eosmat_str(&material.to_json().unwrap()).unwrap();
        assert_eq!(restored.document, material.document);
        assert_eq!(
            restored
                .record(&identifier)
                .unwrap()
                .pressure(v, 1000.0)
                .unwrap(),
            pressure
        );
        assert!((record.volume(pressure, 1000.0).unwrap() - v).abs() < 1e-6);
    }
}
